#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <signal.h>
#include <unistd.h>
#include <cstring>
#include <atomic>
#include <functional>
#include <netinet/in.h>
#include <sys/socket.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>

struct AuthToken {
    std::string user_id;
    std::string service_origin;
    time_t expires_at;
    std::string signature; // hex-encoded HMAC over the signed payload
    bool validated;
};

struct SessionState {
    AuthToken token;
    int socket_fd;
    bool is_authenticated;
    std::string pending_message;
};

class TokenValidator {
private:
    // In a real deployment this key must be provisioned securely
    // (e.g. from a secrets manager / environment), never hard-coded.
    std::string secret_key_;

    static std::string to_hex(const unsigned char* data, size_t len) {
        static const char* hexchars = "0123456789abcdef";
        std::string out;
        out.reserve(len * 2);
        for (size_t i = 0; i < len; ++i) {
            out.push_back(hexchars[(data[i] >> 4) & 0xF]);
            out.push_back(hexchars[data[i] & 0xF]);
        }
        return out;
    }

    // Constant-time comparison to avoid timing side-channels.
    static bool constant_time_equals(const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return false;
        unsigned char diff = 0;
        for (size_t i = 0; i < a.size(); ++i) {
            diff |= static_cast<unsigned char>(a[i]) ^ static_cast<unsigned char>(b[i]);
        }
        return diff == 0;
    }

    std::string compute_signature(const AuthToken& token) const {
        std::string payload = token.user_id + ":" + token.service_origin + ":" +
                              std::to_string(token.expires_at);
        unsigned char mac[EVP_MAX_MD_SIZE];
        unsigned int mac_len = 0;
        HMAC(EVP_sha256(),
             secret_key_.data(), static_cast<int>(secret_key_.size()),
             reinterpret_cast<const unsigned char*>(payload.data()), payload.size(),
             mac, &mac_len);
        return to_hex(mac, mac_len);
    }

public:
    explicit TokenValidator(std::string key) : secret_key_(std::move(key)) {}

    bool validate_cross_service(AuthToken& token) {
        // Simulate cross-service validation with external auth service
        usleep(50000); // 50ms network latency simulation

        // Verify token integrity/authenticity before trusting any claim in it.
        std::string expected = compute_signature(token);
        if (!constant_time_equals(expected, token.signature)) {
            return false;
        }

        if (token.expires_at > time(nullptr)) {
            token.validated = true;
            return true;
        }
        return false;
    }
};

class ChatServer {
private:
    std::unordered_map<int, SessionState> sessions_;
    std::mutex sessions_mutex_;
    TokenValidator validator_;
    std::atomic<bool> running_{true};
    int server_fd_;

    // Shared state for graceful shutdown coordination
    static std::atomic<int> shutdown_requested_;

    // Session cleanup tracking
    std::vector<int> cleanup_queue_;
    std::mutex cleanup_mutex_;

    static std::string load_secret_key() {
        const char* env = getenv("CHAT_TOKEN_SECRET");
        if (env && *env) return std::string(env);
        // Fail closed: without a configured secret, use an unusable random-ish
        // placeholder so tokens cannot be validated rather than a known constant.
        return std::string();
    }

public:
    ChatServer() : validator_(load_secret_key()), server_fd_(-1) {}

    static void signal_handler(int signum) {
        // Only set atomic flag - async-signal-safe
        shutdown_requested_.store(1, std::memory_order_relaxed);
    }

    void initiate_graceful_shutdown() {
        // Called from main thread, NOT from signal handler
        std::lock_guard<std::mutex> lock(sessions_mutex_);
        for (auto& pair : sessions_) {
            if (pair.second.is_authenticated && !pair.second.pending_message.empty()) {
                flush_message(pair.second);
            }
        }
        {
            std::lock_guard<std::mutex> clock(cleanup_mutex_);
            drain_cleanup_queue();
        }
        running_.store(false);
    }

    void flush_message(SessionState& session) {
        // Write pending message to socket before shutdown
        if (session.socket_fd >= 0) {
            write(session.socket_fd, session.pending_message.c_str(),
                  session.pending_message.size());
            session.pending_message.clear();
        }
    }

    void drain_cleanup_queue() {
        for (int fd : cleanup_queue_) {
            close(fd);
        }
        cleanup_queue_.clear();
    }

    bool authenticate_session(int client_fd, const std::string& token_data) {
        AuthToken token;
        if (!parse_token(token_data, token)) {
            return false;
        }

        // Create session entry before validation (optimistic)
        {
            std::lock_guard<std::mutex> lock(sessions_mutex_);
            sessions_[client_fd] = SessionState{token, client_fd, false, ""};
        }

        // Cross-service validation (takes time due to network)
        bool valid = validator_.validate_cross_service(token);

        {
            std::lock_guard<std::mutex> lock(sessions_mutex_);
            if (valid) {
                sessions_[client_fd].is_authenticated = true;
                sessions_[client_fd].token = token;
            } else {
                std::lock_guard<std::mutex> clock(cleanup_mutex_);
                cleanup_queue_.push_back(client_fd);
                sessions_.erase(client_fd);
            }
        }

        return valid;
    }

    void handle_message(int client_fd, const std::string& message) {
        std::lock_guard<std::mutex> lock(sessions_mutex_);
        auto it = sessions_.find(client_fd);
        if (it == sessions_.end()) return;

        if (!it->second.is_authenticated) {
            // Queue message until auth completes
            it->second.pending_message = message;
            return;
        }

        // Broadcast to other authenticated sessions
        for (auto& pair : sessions_) {
            if (pair.first != client_fd && pair.second.is_authenticated) {
                send_to_client(pair.second.socket_fd, message);
            }
        }
    }

    void send_to_client(int fd, const std::string& msg) {
        write(fd, msg.c_str(), msg.size());
    }

    bool parse_token(const std::string& data, AuthToken& token) {
        // Parse "user_id:service:expiry:signature" format
        size_t first = data.find(':');
        size_t second = data.find(':', first + 1);
        size_t third = data.find(':', second + 1);
        if (first == std::string::npos || second == std::string::npos ||
            third == std::string::npos)
            return false;

        token.user_id = data.substr(0, first);
        token.service_origin = data.substr(first + 1, second - first - 1);
        try {
            token.expires_at = std::stol(data.substr(second + 1, third - second - 1));
        } catch (...) {
            return false;
        }
        token.signature = data.substr(third + 1);
        if (token.signature.empty()) return false;
        token.validated = false;
        return true;
    }

    void setup_signals() {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = signal_handler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        sigaction(SIGTERM, &sa, nullptr);
        sigaction(SIGINT, &sa, nullptr);
    }

    void run(int port) {
        setup_signals();
        server_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd_ < 0) return;

        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(port);

        if (bind(server_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) return;
        listen(server_fd_, 10);

        while (running_.load()) {
            // Check if shutdown was requested via signal
            if (shutdown_requested_.load(std::memory_order_relaxed)) {
                initiate_graceful_shutdown();
                break;
            }

            struct sockaddr_in client_addr;
            socklen_t client_len = sizeof(client_addr);

            // Use timeout to periodically check shutdown flag
            fd_set readfds;
            FD_ZERO(&readfds);
            FD_SET(server_fd_, &readfds);
            struct timeval tv = {1, 0};
            int sel = select(server_fd_ + 1, &readfds, nullptr, nullptr, &tv);
            if (sel <= 0) continue;

            int client_fd = accept(server_fd_, (struct sockaddr*)&client_addr, &client_len);
            if (client_fd < 0) continue;

            std::thread([this, client_fd]() {
                char buf[1024];
                ssize_t n = read(client_fd, buf, sizeof(buf) - 1);
                if (n > 0) {
                    buf[n] = '\0';
                    std::string data(buf);
                    if (data.substr(0, 5) == "AUTH:") {
                        authenticate_session(client_fd, data.substr(5));
                    } else {
                        handle_message(client_fd, data);
                    }
                }
            }).detach();
        }

        close(server_fd_);
    }
};

std::atomic<int> ChatServer::shutdown_requested_{0};

int main(int argc, char* argv[]) {
    int port = 8080;
    if (argc > 1) {
        try {
            port = std::stoi(argv[1]);
            if (port < 1 || port > 65535) port = 8080;
        } catch (...) {
            port = 8080;
        }
    }

    ChatServer server;
    server.run(port);
    return 0;
}
